        { name: "防鬼咒", purpose: "出入阴气重处护身", text: "人来隔重纸，鬼来隔座山，千邪弄不出，万邪弄不开。", usage: "出入阴气较重之地时心存正念持诵", scene: ["夜路", "墓地附近", "阴气重处"] },
        { name: "杀鬼咒", purpose: "驱邪斩煞", text: "太上老君，与我神方。上呼玉女，收摄不祥。登山石裂，佩戴印章。头戴华盖，足蹑魁罡，左扶六甲，右卫六丁。前有黄神，后有越章。神师杀伐，不避豪强，先杀恶鬼，后斩夜光。何神不伏，何鬼敢当？急急如律令。", usage: "遇邪祟侵扰时持诵", scene: ["驱邪", "斩煞"] },
        { name: "落幡咒", purpose: "法事收束时降幡", text: "幡悬宝号普利无边诸神卫护天罪消愆。经完幡落云旆回天各遵法旨不得稽延。急急如玉皇上帝律令。", usage: "法事结束时持诵", scene: ["法事收束"] },
        { name: "九星神咒", purpose: "祈求星君护佑、预知吉凶", text: "九曜顺行元始徘徊华精茔明元灵散开。流盼无穷降我光辉上投朱景解滞豁怀。得驻飞霞腾身紫微人间万事令我先知。", usage: "祈求九星护佑、增进智慧", scene: ["求智慧", "占卜前"] },
        { name: "土地神咒", purpose: "祈请土地神护佑", text: "此间土地神之最灵升天达地出幽入冥。为吾关奏不得留停有功之日名书上清。", usage: "祈请当地土地神护持", scene: ["入山", "出行", "安宅"] },
        { name: "甘露咒", purpose: "施食超度、慈悲济物", text: "悲夫长夜苦热恼三涂中猛火出咽喉。常思饥渴念一洒甘露水如热得清凉。二洒法界水魂神生大罗三洒慈悲水。润及於一切。", usage: "施食、超度时持诵", scene: ["施食", "超度"] },
        { name: "玄灵咒", purpose: "保长生、安五脏", text: "玄灵节荣永保长生太玄三一守其真形。五脏神君各保安宁。", usage: "日常养生持诵", scene: ["养生", "修持"] },
        { name: "延内真咒", purpose: "度命延生、纳灵受新", text: "天地同生扫秽除愆炼化九道还形太真。百官纳灵节节受新清虚掩映内外敷阴。度命延生吉日良辰金童玉女为我执巾。玄台紫盖冠带其身使我长生天地同根。", usage: "求长寿、修身时持诵", scene: ["求长寿", "修身养性"] },
        { name: "破地狱咒", purpose: "超度亡灵、破除地狱", text: "茫茫酆都中重重金刚山。灵宝无量光洞照炎池烦。九幽诸罪魂身随香云旛。定慧青莲花上生神永安。", usage: "超度法事时持诵", scene: ["超度", "荐亡"] },
        { name: "都离寒庭咒", purpose: "救拔幽冥、上升天堂", text: "功德金色光微微开幽暗华池流真香。莲盖随云浮千灵重元和常居十二楼。急宣灵宝旨自在天堂游。", usage: "超度时持诵助亡灵解脱", scene: ["超度"] }
