  // ================================================================
  // 第十二篇：传统二十四节气养生
  // ================================================================
  solar_terms: {
    title: "二十四节气养生口诀",
    source: "传统节气养生智慧",
    count: 24,
    mantras: [
      { name: "立春养生", text: "立春雨水到，早起晚睡觉。护肝为本，助阳生发。少酸多甘，疏肝理气。", purpose: "立春养生要诀", scene: ["立春", "春季养生"] },
      { name: "雨水养生", text: "雨水节气到，春寒料峭。健脾祛湿，多食粥汤。捂下身暖，防倒春寒。", purpose: "雨水养生要诀", scene: ["雨水", "祛湿"] },
      { name: "惊蛰养生", text: "惊蛰闻雷起，春捂防病。疏肝理气，早睡早起。多食清淡，少吃辛辣。", purpose: "惊蛰养生要诀", scene: ["惊蛰", "防病"] },
      { name: "春分养生", text: "春分阴阳半，昼夜正等长。疏肝养肝，平补阴阳。早睡早起，户外运动。", purpose: "春分养生要诀", scene: ["春分", "平衡"] },
      { name: "清明养生", text: "清明时节雨，踏青正当时。养肝明目，少吃发物。扫墓抒怀，情志调畅。", purpose: "清明养生要诀", scene: ["清明", "踏青"] },
      { name: "谷雨养生", text: "谷雨断霜尽，种瓜点豆时。健脾祛湿，谨防过敏。多食香椿，防春火。", purpose: "谷雨养生要诀", scene: ["谷雨", "祛湿"] },
      { name: "立夏养生", text: "立夏养心忙，晚睡早起养心脏。多食清淡，少食油腻。安神定志，心静自然凉。", purpose: "立夏养生要诀", scene: ["立夏", "养心"] },
      { name: "小满养生", text: "小满江河满，湿热易缠绵。健脾祛湿，清热利湿。莫贪凉食，伤人脾胃。", purpose: "小满养生要诀", scene: ["小满", "祛湿"] },
      { name: "芒种养生", text: "芒种忙收麦，养生防暑热。早起运动，午睡小憩。吃苦味，食清淡，多补水。", purpose: "芒种养生要诀", scene: ["芒种", "防暑"] },
      { name: "夏至养生", text: "夏至一阴生，昼长夜最短。养心护阳，午睡养神。多食酸味，生津止渴。", purpose: "夏至养生要诀", scene: ["夏至", "养心"] },
      { name: "小暑养生", text: "小暑不算热，心静自然凉。少动多静，避暑防晒。多食莲子，清心安神。", purpose: "小暑养生要诀", scene: ["小暑", "避暑"] },
      { name: "大暑养生", text: "大暑三伏天，湿热最难缠。防暑降温，多饮绿豆汤。冬病夏治，贴三伏贴。", purpose: "大暑养生要诀", scene: ["大暑", "三伏"] },
      { name: "立秋养生", text: "立秋还暑期，秋老虎发威。润肺防燥，少吃辛辣。早睡早起，收敛神气。", purpose: "立秋养生要诀", scene: ["立秋", "润肺"] },
      { name: "处暑养生", text: "处暑出伏天，秋燥渐明显。滋阴润燥，多食秋梨。早睡早起，化解秋乏。", purpose: "处暑养生要诀", scene: ["处暑", "润燥"] },
      { name: "白露养生", text: "白露身不露，秋冻要适度。养肺润燥，多食百合。早卧早起，避寒保暖。", purpose: "白露养生要诀", scene: ["白露", "保暖"] },
      { name: "秋分养生", text: "秋分昼夜平，阴阳正相当。养肺润燥，适度秋冻。早睡早起，登高望远。", purpose: "秋分养生要诀", scene: ["秋分", "平衡"] },
      { name: "寒露养生", text: "寒露脚不露，养生防寒凉。养阴润燥，少辛多酸。早卧早起，养护肺脏。", purpose: "寒露养生要诀", scene: ["寒露", "防寒"] },
      { name: "霜降养生", text: "霜降天渐冷，秋冬要交关。养肺润燥，防寒保暖。多食萝卜，顺气化痰。", purpose: "霜降养生要诀", scene: ["霜降", "防寒"] },
      { name: "立冬养生", text: "立冬万物藏，养肾正当时。早睡晚起，必待日光。多食黑色，补肾填精。", purpose: "立冬养生要诀", scene: ["立冬", "养肾"] },
      { name: "小雪养生", text: "小雪封地不上冻，养肾防寒莫放松。多食温热，少食寒冷。早睡晚起，阳光取暖。", purpose: "小雪养生要诀", scene: ["小雪", "防寒"] },
      { name: "大雪养生", text: "大雪封河冻，养藏正当时。早睡晚起，避寒就温。多食温补，羊肉当归。", purpose: "大雪养生要诀", scene: ["大雪", "温补"] },
      { name: "冬至养生", text: "冬至一阳生，阴阳交替时。养肾护阳，饺子汤圆。早睡晚起，晒太阳补钙。", purpose: "冬至养生要诀", scene: ["冬至", "护阳"] },
      { name: "小寒养生", text: "小寒最冷天，防寒保暖先。养肾温阳，羊肉当归。早睡晚起，防寒入骨。", purpose: "小寒养生要诀", scene: ["小寒", "防寒"] },
      { name: "大寒养生", text: "大寒年将尽，五九六九河边看柳。冬藏最后，养肾固本。早睡晚起，春捂秋冻。", purpose: "大寒养生要诀", scene: ["大寒", "冬藏"] }
    ]
  },

