  cantongqi: {
    title: "《周易参同契》选编",
    source: "东汉·魏伯阳《周易参同契》",
    count: 5,
    mantras: [
      { name: "参同契总纲", text: "乾坤者，易之门户，众卦之父母。坎离匡郭，运毂正轴。", source: "《周易参同契》", purpose: "内丹总纲", usage: "内丹修炼参照", scene: ["内丹"] },
      { name: "药物直说", text: "药物非同类，难为规矩。", source: "《周易参同契》", purpose: "药物同类", usage: "内丹修炼参照", scene: ["内丹", "药物"] },
      { name: "火候直说", text: "周旋十二节，节尽更须亲。气索命将绝，体死神光灭。", source: "《周易参同契》", purpose: "火候进退", usage: "内丹火候参照", scene: ["内丹", "火候"] },
      { name: "丹成验证", text: "颜色悦泽好，鬓发皆变黑。齿落更生细，老翁成丁男。", source: "《周易参同契》", purpose: "丹成验证", usage: "内丹验证参照", scene: ["内丹", "验证"] },
      { name: "参同契结语", text: "参同契者，敷陈梗概，不能究其深妙。惟审思之，深思求之。", source: "《周易参同契》", purpose: "参同契总结", usage: "内丹修炼参照", scene: ["内丹"] }
    ]
  },

  // ================================================================
  // 第二十七篇：天台止观法门
  // ================================================================
  tiantai_zhiguan: {
    title: "天台止观法门",
    source: "隋·智顗大师《小止观》《摩诃止观》",
    count: 8,
    mantras: [
      { name: "止观总纲", text: "若夫泥洹之法，入乃多途。论其急要，不出止观二法。所以然者，止乃伏结之初门，观是断惑之正要。", source: "《小止观》", purpose: "止观总纲", usage: "止观修习参照", scene: ["止观", "禅修"] },
      { name: "二十五方便", text: "具五缘、诃五欲、弃五盖、调五事、行五法，二十五方便。", source: "《小止观》", purpose: "止观前方便", usage: "止观修习参照", scene: ["止观", "方便"] },
      { name: "调五事", text: "调食不饥不饱，调睡不节不恣，调身不宽不急，调息不涩不滑，调心不沉不浮。", source: "《小止观》", purpose: "调身息心", usage: "打坐调身参考", scene: ["止观", "调身"] },
      { name: "修止三法", text: "一者系缘守境止，二者制心止，三者体真止。", source: "《小止观》", purpose: "修止三种方法", usage: "止观修习参照", scene: ["止观"] },
      { name: "修观二法", text: "一者对治观，如不净观、慈心观等；二者正观，观诸法实相。", source: "《小止观》", purpose: "修观二种方法", usage: "止观修习参照", scene: ["止观"] },
      { name: "觉魔事", text: "烦恼魔、阴入界魔、死魔、鬼神魔，四种魔事须觉察。", source: "《小止观》", purpose: "觉察魔事", usage: "止观修习参照", scene: ["止观", "魔事"] },
      { name: "治病患", text: "用止治病，用观治病，用气治病，用息治病，用方术治病。", source: "《小止观》", purpose: "止观治病", usage: "禅修治病参考", scene: ["止观", "治病"] },
      { name: "证果", text: "若能如是修止观者，即能成就一切禅定智慧，证得无漏无为之果。", source: "《小止观》", purpose: "止观证果", usage: "止观修习参照", scene: ["止观", "证果"] }
    ]
  },

