  // ================================================================
  // 第三十九篇：了凡四训精选口诀
  // ================================================================
  liaofan_koujue: {
    title: "了凡四训精选口诀",
    source: "明代·袁了凡《了凡四训》",
    count: 15,
    mantras: [
      { name: "立命", text: "命由我作，福自己求。", source: "《了凡四训》", purpose: "命运自主", scene: ["立命"] },
      { name: "改过", text: "务要日日知非，日日改过。一日不知非，即一日安于自是；一日无过可改，即一日无步可进。", source: "《了凡四训》", purpose: "日日改过", scene: ["修身"] },
      { name: "积善", text: "积善之家，必有余庆。", source: "《了凡四训》", purpose: "积善余庆", scene: ["积善"] },
      { name: "谦虚", text: "满招损，谦受益。", source: "《了凡四训》", purpose: "谦虚受益", scene: ["谦虚"] },
      { name: "改命", text: "一切福田，不离方寸。从心而觅，感无不通。", source: "《了凡四训》", purpose: "从心改命", scene: ["立命", "修心"] },
      { name: "行善", text: "人为善，福虽未至，祸已远离；人为恶，祸虽未至，福已远离。", source: "《了凡四训》", purpose: "善恶福祸", scene: ["行善"] },
      { name: "改过三心", text: "改过者，第一要发耻心，第二要发畏心，第三要发勇心。", source: "《了凡四训》", purpose: "改过三心", scene: ["修身"] },
      { name: "事理", text: "有志于功名者，必得功名；有志于富贵者，必得富贵。人之有志，如树之有根。", source: "《了凡四训》", purpose: "立志之要", scene: ["立志"] },
      { name: "谦德", text: "惟谦受福。", source: "《了凡四训》", purpose: "谦德受福", scene: ["谦虚"] },
      { name: "十善", text: "与人为善，爱敬存心，成人之美，劝人为善，救人危急，兴建大利，舍财作福，护持正法，敬重尊长，爱惜物命。", source: "《了凡四训》", purpose: "十善之行", scene: ["行善"] },
      { name: "心性", text: "过有千端，惟心所造。吾心不动，过安从生？", source: "《了凡四训》", purpose: "心为本源", scene: ["修心"] },
      { name: "天道", text: "天道亏盈而益谦，地道变盈而流谦，鬼神害盈而福谦，人道恶盈而好谦。", source: "《了凡四训》", purpose: "谦受益满招损", scene: ["谦虚"] },
      { name: "培养", text: "善心真切，即一念可及万善。", source: "《了凡四训》", purpose: "真心行善", scene: ["行善"] },
      { name: "命运", text: "极善之人，数固拘他不定；极恶之人，数亦拘他不定。", source: "《了凡四训》", purpose: "善恶超越命运", scene: ["立命"] },
      { name: "精进", text: "一日不知非，即一日安于自是。", source: "《了凡四训》", purpose: "不可自是", scene: ["修身"] }
    ]
  },

  // ================================================================
  // 第四十篇：增广贤文补编二十条
  // ================================================================
  zengguang_more: {
    title: "增广贤文补编",
    source: "《增广贤文》",
    count: 20,
    mantras: [
      { name: "明理", text: "来说是非者，便是是非人。", source: "《增广贤文》", purpose: "明辨是非", scene: ["处世"] },
      { name: "务实", text: "莫说年纪小，容易抛人去。莫说时刻短，一去不复来。", source: "《增广贤文》", purpose: "珍惜时光", scene: ["惜时"] },
      { name: "忍耐", text: "小洞不补，大洞吃苦。", source: "《增广贤文》", purpose: "防微杜渐", scene: ["防微"] },
      { name: "报恩", text: "滴水之恩，当涌泉相报。", source: "《增广贤文》", purpose: "知恩图报", scene: ["报恩"] },
      { name: "团结", text: "一个篱笆三个桩，一个好汉三个帮。", source: "《增广贤文》", purpose: "团结互助", scene: ["团结"] },
      { name: "戒骄", text: "虚心使人进步，骄傲使人落后。", source: "古训", purpose: "戒骄戒躁", scene: ["谦虚"] },
      { name: "做事", text: "世上无难事，只怕有心人。", source: "《增广贤文》", purpose: "有志竟成", scene: ["励志"] },
      { name: "健康", text: "身体发肤，受之父母，不敢毁伤。", source: "《孝经》", purpose: "珍爱身体", scene: ["健康"] },
      { name: "义利", text: "君子喻于义，小人喻于利。", source: "《论语·里仁》", purpose: "义利之辨", scene: ["修身"] },
      { name: "诚信", text: "言必信，行必果。", source: "《论语·子路》", purpose: "诚信果决", scene: ["诚信"] },
      { name: "宽厚", text: "宰相肚里能撑船。", source: "民间谚语", purpose: "宽宏大量", scene: ["宽容"] },
      { name: "自力", text: "求人不如求己。", source: "《增广贤文》", purpose: "自力更生", scene: ["自强"] },
      { name: "远见", text: "人无远虑，必有近忧。", source: "《论语·卫灵公》", purpose: "远见卓识", scene: ["远虑"] },
      { name: "克己", text: "胜人者有力，自胜者强。", source: "《道德经·第三十三章》", purpose: "克己自强", scene: ["修身"] },
      { name: "择邻", text: "孟母三迁，择邻而居。", source: "《三字经》", purpose: "环境影响", scene: ["家教"] },
      { name: "心正", text: "心正不怕影子斜。", source: "民间谚语", purpose: "心正行端", scene: ["修身"] },
      { name: "勤学", text: "书山有路勤为径，学海无涯苦作舟。", source: "韩愈", purpose: "勤学苦练", scene: ["劝学"] },
      { name: "磨砺", text: "宝剑锋从磨砺出，梅花香自苦寒来。", source: "《警世贤文》", purpose: "艰苦磨砺", scene: ["励志"] },
      { name: "知人", text: "路遥知马力，日久见人心。", source: "《增广贤文》", purpose: "日久见人心", scene: ["识人"] },
      { name: "应变", text: "车到山前必有路，船到桥头自然直。", source: "民间谚语", purpose: "随遇而安", scene: ["心态"] }
    ]
  },

