  function objToHtml(obj, depth) {
    depth = depth || 0;
    let html = '';
    if (typeof obj === 'string') return obj;
    for (let key in obj) {
      if (typeof obj[key] === 'string') {
        html += '<h4>' + key + '</h4><p>' + obj[key] + '</p>';
      } else if (typeof obj[key] === 'object') {
        html += '<h4>' + key + '</h4>';
        for (let subkey in obj[key]) {
          html += '<p><b>' + subkey + '</b>：' + obj[key][subkey] + '</p>';
        }
      }
    }
    return html;
  }

